  void operator[]=(int index, String value) {
    m = "[\$index]=\$value";
  }
}

extension on C {
  String get getter => "Extension getter";
  String get m => "m getter";
  void set setter(String v) {}
  void set m(String v) {}
  String method(int i) => "Extension: \$i";
